style.css:
html > body:before,
html > body:after {
    position:fixed;
    left:5px;
    z-index:99999999;
    width:auto;
    height:auto;
    padding:5px;
    color:#fff;
    font-size:12px;
    font-family:'Helvetica Neue', Helvetica, Arial, sans-serif;
    background:rgba(255, 0, 255, 0.75);
    opacity:0.50;
    letter-spacing:1px;
    pointer-events:none;
}


html > body:before {
    content: "Extra Small (XS) | (<576px)"; /* Extra Small - xs */
    bottom:5px;
}


html > body:after {
    content: "Orientation: Portrait";
    bottom:35px;
}


@media (min-width: 576px) { html > body:before { content: "Small (SM) | (\2265 576px)";} }			        /* Small - SM */
@media (min-width: 768px) { html > body:before { content: "Medium (MD) | (\2265 768px)";} }			        /* Medium - MD */
@media (min-width: 992px) { html > body:before { content: "Large (LG) | (\2265 992px)";} }			        /* Large - LG */
@media (min-width: 1200px) { html > body:before { content: "Extra Large (XL) | (\2265 1200px)";} }	        /* Extra Large - XL */
@media (min-width: 1400px) { html > body:before { content: "Extra Extra Large (XXL) | (\2265 1200px)";} }	/* Extra Extra Large - XXL */


/* Styles for screens in portrait orientation */
@media screen and (orientation: portrait) {
  html > body:after {
    content: "Orientation: Portrait";
  }
}

/* Styles for screens in landscape orientation */
@media screen and (orientation: landscape) {
  html > body:after {
    content: "Orientation: Landscape";
  }
}
